  'PI_DISH_OMP_COMMAND',
  'PI_DISH_PRIME_COMMAND',
  'PI_DISH_REAL_OMP_BIN',
  'PI_DISH_REAL_PRIME_BIN',
  'PI_DISH_REAL_BUN_BIN_DIR',
